<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0"/>
  <title>Lotte Tower Conceptual Model</title>
  <style>
    body {
      margin: 0;
      font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
      background-color: #0e0e0e;
      color: #f0f0f0;
    }
    #container {
      width: 100vw;
      height: 100vh;
      position: relative;
      overflow: hidden;
    }
    #controls {
      position: absolute;
      top: 20px;
      left: 20px;
      z-index: 10;
      background: rgba(0, 0, 0, 0.6);
      padding: 15px;
      border-radius: 8px;
    }
    #controls label,
    #controls button {
      display: block;
      margin: 8px 0;
      font-size: 19px;
      color: #f0f0f0;
    }
    #controls select {
      font-size: 19px;
      padding: 5px;
    }
    #drawings {
      position: absolute;
      bottom: 20px;
      left: 20px;
      z-index: 10;
      background: rgba(0, 0, 0, 0.6);
      padding: 15px;
      border-radius: 8px;
    }
    #drawings label,
    #drawings button {
      display: block;
      margin: 8px 0;
      font-size: 19px;
      color: #f0f0f0;
    }
    #drawings select {
      font-size: 19px;
      padding: 5px;
    }
    #info {
      position: absolute;
      top: 20px;
      right: 20px;
      z-index: 10;
      background: rgba(0, 0, 0, 0.6);
      padding: 15px;
      border-radius: 8px;
    }
    #info p {
      font-size: 19px;
      margin: 5px 0;
    }
  </style>
</head>
<body>
  <div id="container">
    <div id="controls">
      <label for="stageSelect">Model Stage:</label>
      <select id="stageSelect">
        <option value="initial">Initial Concept</option>
        <option value="refined">Refined Geometry</option>
        <option value="final">Final Form</option>
      </select>
      <button id="resetCamera">Reset Camera</button>
    </div>
    <div id="drawings">
      <label for="drawingSelect">Drawing Type:</label>
      <select id="drawingSelect">
        <option value="site">Site Plan</option>
        <option value="floor">Floor Plan</option>
        <option value="elevation">Elevation</option>
        <option value="section">Section</option>
      </select>
    </div>
    <div id="info">
      <p><strong>Model:</strong> Lotte Tower Concept</p>
      <p><strong>Units:</strong> Meters</p>
      <p><strong>Assumptions:</strong> Conceptual geometry, not to scale</p>
    </div>
  </div>

  <script src="https://cdn.jsdelivr.net/npm/three@0.158.0/build/three.min.js"></script>
  <script src="https://cdn.jsdelivr.net/npm/three@0.158.0/examples/js/controls/OrbitControls.js"></script>
  <script>
    // Global runtime
    const runtime = {
      scene: null,
      camera: null,
      renderer: null,
      modelGroup: null,
      controls: null,
      drawingCanvas: null,
      drawingCtx: null,
      drawingType: 'initial',
      modelStages: {
        initial: {
          color: 0x333333,
          radiusTop: 10,
          radiusBottom: 15,
          height: 100
        },
        refined: {
          color: 0x555555,
          radiusTop: 8,
          radiusBottom: 12,
          height: 100
        },
        final: {
          color: 0x777777,
          radiusTop: 6,
          radiusBottom: 10,
          height: 100
        }
      }
    };

    // Initialize scene
    function initScene() {
      const container = document.getElementById('container');
      runtime.scene = new THREE.Scene();
      runtime.camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 1000);
      runtime.camera.position.set(30, 30, 30);
      runtime.renderer = new THREE.WebGLRenderer({ antialias: true });
      runtime.renderer.setSize(window.innerWidth, window.innerHeight);
      container.appendChild(runtime.renderer.domElement);

      runtime.controls = new THREE.OrbitControls(runtime.camera, runtime.renderer.domElement);
      runtime.controls.enableDamping = true;
      runtime.controls.dampingFactor = 0.05;
      runtime.controls.enablePan = false;

      // Add ambient light
      const ambientLight = new THREE.AmbientLight(0xffffff, 0.4);
      runtime.scene.add(ambientLight);

      // Add directional light
      const directionalLight = new THREE.DirectionalLight(0xffffff, 0.8);
      directionalLight.position.set(10, 20, 10);
      runtime.scene.add(directionalLight);

      // Create model
      runtime.modelGroup = new THREE.Group();
      runtime.scene.add(runtime.modelGroup);
      updateModel('initial');
    }

    // Update model based on stage
    function updateModel(stage) {
      if (runtime.modelGroup) {
        runtime.modelGroup.clear();
      }

      const stageData = runtime.modelStages[stage];
      const geometry = new THREE.CylinderGeometry(stageData.radiusBottom, stageData.radiusTop, stageData.height, 32);
      const material = new THREE.MeshStandardMaterial({ color: stageData.color, wireframe: true });
      const cylinder = new THREE.Mesh(geometry, material);
      cylinder.rotation.x = Math.PI / 2;
      runtime.modelGroup.add(cylinder);
    }

    // Reset camera
    function resetCamera() {
      runtime.camera.position.set(30, 30, 30);
      runtime.camera.lookAt(0, 0, 0);
      runtime.controls.update();
    }

    // Handle drawing types
    function updateDrawing(type) {
      const canvas = document.createElement('canvas');
      canvas.width = 400;
      canvas.height = 300;
      const ctx = canvas.getContext('2d');
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = '#000';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = '#fff';
      ctx.font = '19px sans-serif';
      ctx.fillText(`Drawing: ${type}`, 10, 20);
      ctx.fillText(`Conceptual Geometry`, 10, 40);
      ctx.fillText(`Units: Meters`, 10, 60);
      ctx.fillText(`Assumptions: Not to scale`, 10, 80);

      const drawingsDiv = document.getElementById('drawings');
      if (runtime.drawingCanvas) {
        drawingsDiv.removeChild(runtime.drawingCanvas);
      }
      runtime.drawingCanvas = canvas;
      drawingsDiv.appendChild(canvas);
    }

    // Keyboard controls
    document.addEventListener('keydown', (e) => {
      if (e.key === 'ArrowLeft') {
        runtime.camera.rotation.y += 0.05;
      } else if (e.key === 'ArrowRight') {
        runtime.camera.rotation.y -= 0.05;
      } else if (e.key === 'ArrowUp') {
        runtime.camera.position.z -= 1;
      } else if (e.key === 'ArrowDown') {
        runtime.camera.position.z += 1;
      }
      runtime.controls.update();
    });

    // Event listeners
    document.getElementById('stageSelect').addEventListener('change', (e) => {
      updateModel(e.target.value);
    });

    document.getElementById('resetCamera').addEventListener('click', () => {
      resetCamera();
    });

    document.getElementById('drawingSelect').addEventListener('change', (e) => {
      updateDrawing(e.target.value);
    });

    // Initialize
    initScene();

    // Animation loop
    function animate() {
      requestAnimationFrame(animate);
      runtime.controls.update();
      runtime.renderer.render(runtime.scene, runtime.camera);
    }

    animate();

    // Responsive resize
    window.addEventListener('resize', () => {
      runtime.camera.aspect = window.innerWidth / window.innerHeight;
      runtime.camera.updateProjectionMatrix();
      runtime.renderer.setSize(window.innerWidth, window.innerHeight);
    });
  </script>
</body>
</html>
